class Solution {public long[] solve(long aNum,long aDen,long bNum,long bDen,String operation){long n,d;if(operation.equals("+")||operation.equals("-")){n=aNum*bDen+(operation.equals("+")?bNum:-bNum)*aDen;d=aDen*bDen;}else if(operation.equals("*")){n=aNum*bNum;d=aDen*bDen;}else{n=aNum*bDen;d=aDen*bNum;}if(d<0){n=-n;d=-d;}long x=Math.abs(n),y=d;while(y!=0){long t=x%y;x=y;y=t;}return new long[]{n/x,d/x};}}